def solve(data):
    balances = dict(data.get('opening', {}))
    events = data.get('events', [])
    cutoff = data.get('cutoff', 10**9)

    winners = {}
    for position, event in enumerate(events):
        if event.get('sequence', 0) > cutoff:
            continue

        if 'id' in event:
            identity = ('id', event['id'])
        else:
            identity = ('anonymous', position)

        revision = event.get('revision', 0)
        previous = winners.get(identity)
        if previous is None or (revision, position) >= (previous[0], previous[1]):
            winners[identity] = (revision, position, event)

    for _, _, event in winners.values():
        if event.get('void', False):
            continue
        key = f"{event.get('account', 'default')}|{event.get('currency', 'USD')}"
        balances[key] = balances.get(key, 0) + amount(event, data.get('rounding', 'half_up'))

    return {'balances': balances}
